# Moini et al. - The Pharmacy Technician: A Comprehensive Approach.
# Chapter list: 5th edition (2026), from National Geographic Learning's product data (ngl.cengage.com).
# Summaries cover each chapter's standard topics; they are written for this site, not copied from the book.

C = [
    (1, "History of Pharmacy", [
        "Pharmacy has roots in ancient civilizations that used plants as medicine; the Ebers Papyrus from Egypt lists hundreds of remedies. Hippocrates and Galen shaped early medicine, and pharmacy separated from medicine in the Middle Ages. Modern pharmacy grew with drug discoveries like insulin and penicillin and with laws regulating drug safety.",
        "Pharmacy technicians assist pharmacists with preparing and dispensing medications, inventory, and customer service. Certification (CPhT) is earned through the PTCB or NHA exams, and many states require registration or licensure.",
    ], ["Ebers Papyrus = early drug records", "Galen: early drug preparation", "Technicians assist pharmacists", "CPhT through PTCB or NHA"]),
    (2, "The Foundation of Pharmaceutical Care", [
        "Pharmaceutical care means the pharmacist takes responsibility for a patient's drug therapy outcomes. Medication therapy management (MTM) reviews all of a patient's medications to prevent problems.",
        "Technicians support care by gathering patient information, maintaining profiles, and referring clinical questions to the pharmacist. Professionalism, teamwork, and patient-centered service are essential.",
    ], ["Pharmaceutical care focuses on outcomes", "MTM reviews all medications", "Technicians refer clinical questions to the pharmacist", "Patient-centered service"]),
    (3, "Pharmacy Law and Ethics for Technicians", [
        "Key laws include the Pure Food and Drug Act (1906), the Food, Drug, and Cosmetic Act (1938, required drug safety), the Durham-Humphrey Amendment (1951, created prescription vs. OTC drugs), the Kefauver-Harris Amendment (1962, required effectiveness), the Controlled Substances Act (1970, DEA schedules I–V), the Poison Prevention Packaging Act (child-resistant caps), OBRA '90 (patient counseling), HIPAA (privacy), and the Combat Methamphetamine Epidemic Act (pseudoephedrine limits).",
        "Schedule I drugs have no accepted medical use; Schedule II drugs have high abuse potential and no refills; Schedules III–V have decreasing abuse potential and allow limited refills. Ethics includes confidentiality, honesty, and respect for patients.",
    ], ["Durham-Humphrey: Rx vs. OTC", "Kefauver-Harris: drugs must be effective", "Controlled Substances Act: Schedules I–V", "OBRA '90: counseling; HIPAA: privacy"]),
    (4, "Communication with Patients and Customers", [
        "Good communication includes active listening, clear language, empathy, and appropriate body language. Technicians handle phone calls, greet customers, and resolve complaints calmly.",
        "Special considerations include patients with hearing or vision loss, language barriers (use interpreters), cultural differences, and protecting privacy at the counter. Only the pharmacist provides counseling about medications.",
    ], ["Active listening and empathy", "Use interpreters for language barriers", "Protect privacy at the counter", "Pharmacists counsel patients"]),
    (5, "Pharmaceutical Information and References", [
        "Drug references include the Physicians' Desk Reference (PDR), Drug Facts and Comparisons, the USP-NF (official standards), the Orange Book (therapeutic equivalence of generics), the Red Book (drug prices), the Handbook on Injectable Drugs, and electronic databases such as Lexicomp and Micromedex.",
        "Technicians use references to look up drug names, strengths, dosage forms, and storage requirements, while clinical questions go to the pharmacist.",
    ], ["Orange Book = generic equivalence", "Red Book = drug prices", "USP-NF = official standards", "Handbook on Injectable Drugs for IV compatibility"]),
    (6, "Prescriptions and Processing", [
        "A prescription includes patient information, date, drug name, strength, dosage form, quantity, directions (the 'sig'), refills, and prescriber information and signature. Controlled substance prescriptions also need the prescriber's DEA number.",
        "Processing steps include receiving and reviewing the prescription, entering it into the computer, checking insurance, filling and labeling, and final verification by the pharmacist. Common abbreviations include bid (twice a day), tid (three times), qid (four times), prn (as needed), po (by mouth), and ac/pc (before/after meals).",
    ], ["Sig = directions for use", "DEA number for controlled substances", "Pharmacist does final verification", "bid, tid, qid, prn, po, ac, pc"]),
    (7, "Dosage Forms and Routes of Administration", [
        "Solid forms include tablets (including enteric-coated, extended-release, chewable, and sublingual), capsules, powders, and lozenges. Liquid forms include solutions, suspensions (shake well), syrups, elixirs (contain alcohol), and emulsions. Semisolids include creams, ointments, gels, and suppositories.",
        "Routes include oral, sublingual, buccal, topical, transdermal, inhalation, ophthalmic, otic, nasal, rectal, vaginal, and parenteral (IV, IM, subcutaneous, intradermal). Extended-release and enteric-coated tablets should not be crushed.",
    ], ["Suspensions must be shaken", "Elixirs contain alcohol", "Don't crush ER or enteric-coated tablets", "Parenteral = injection"]),
    (8, "Measurement Systems", [
        "The metric system is the standard in pharmacy: gram (weight), liter (volume), and meter (length), with prefixes kilo- (1,000), milli- (1/1,000), and micro- (1/1,000,000). Household measures include teaspoon (5 mL), tablespoon (15 mL), fluid ounce (30 mL), and cup (240 mL).",
        "Other systems include the apothecary and avoirdupois systems. 1 kg = 2.2 lb; 1 grain ≈ 65 mg. Using a leading zero (0.5 mg) and no trailing zero (5 mg, not 5.0 mg) prevents errors.",
    ], ["kilo 1,000; milli 1/1,000; micro 1/1,000,000", "1 tsp = 5 mL; 1 tbsp = 15 mL; 1 oz = 30 mL", "1 kg = 2.2 lb", "Leading zero yes; trailing zero no"]),
    (9, "Conversion and Calculations", [
        "Pharmacy calculations use ratio and proportion and dimensional analysis. The dose formula is desired ÷ have × quantity. Days' supply = quantity dispensed ÷ quantity used per day.",
        "Other calculations include converting units, percent strength (w/v = grams per 100 mL), dilutions (C1V1 = C2V2), alligation, IV flow rates (mL/hr and drops per minute), and pediatric doses based on weight (mg/kg).",
    ], ["Desired ÷ have × quantity", "Days' supply = quantity ÷ daily use", "C1V1 = C2V2", "% w/v = g per 100 mL"]),
    (10, "Safety in the Workplace", [
        "Pharmacy safety includes OSHA rules, Safety Data Sheets for chemicals, sharps disposal, fire safety, and ergonomic practices. Hazardous drugs such as chemotherapy require special handling, PPE, and disposal (USP 800).",
        "Infection control includes hand hygiene and cleaning work areas. Technicians follow procedures for spills and exposures and report incidents.",
    ], ["SDS for chemicals", "USP 800 = hazardous drugs", "Hand hygiene", "Report spills and exposures"]),
    (11, "Hospital Pharmacy", [
        "Hospital (institutional) pharmacies supply medications to inpatients. Systems include unit-dose dispensing (each dose individually packaged), automated dispensing cabinets on nursing units, floor stock, and crash carts.",
        "Technicians fill medication orders, prepare IV admixtures, restock automated cabinets, and deliver medications. The Pharmacy and Therapeutics (P&T) committee manages the hospital's formulary.",
    ], ["Unit-dose dispensing", "Automated dispensing cabinets", "P&T committee manages the formulary", "Crash carts for emergencies"]),
    (12, "Community Pharmacy", [
        "Community (retail) pharmacies serve the public: chain, independent, and supermarket pharmacies. Technicians take in prescriptions, process insurance, count and label medications, run the register, and help customers find OTC products.",
        "Pharmacists counsel patients, give immunizations, and provide MTM. Technicians must refer questions about drug use, side effects, or OTC recommendations to the pharmacist.",
    ], ["Chain, independent, supermarket pharmacies", "Technicians process and fill prescriptions", "Pharmacists counsel and immunize", "Refer clinical questions"]),
    (13, "Advanced Pharmacy", [
        "Advanced practice settings include home infusion, long-term care, mail-order, specialty, nuclear, and telepharmacy services. Each has unique workflows and regulations.",
        "Technicians may take on advanced roles such as medication reconciliation, sterile compounding, inventory management, and supervising other technicians.",
    ], ["Home infusion and long-term care", "Mail-order and specialty pharmacy", "Nuclear pharmacy = radioactive drugs", "Advanced technician roles"]),
    (14, "Non-Sterile Compounding", [
        "Non-sterile compounding prepares customized medications such as creams, ointments, capsules, and oral liquids, following USP 795. Equipment includes the class A balance, mortar and pestle, spatulas, graduated cylinders, and ointment slabs.",
        "Techniques include trituration (grinding to a fine powder), levigation (mixing a powder with a liquid to make a paste), and geometric dilution (mixing small amounts of drug with equal amounts of base). Records and beyond-use dates are required.",
    ], ["USP 795 = non-sterile compounding", "Trituration = grinding", "Levigation = powder + liquid paste", "Geometric dilution for even mixing"]),
    (15, "Sterile Compounding", [
        "Sterile compounding prepares IV medications, injections, and eye drops using aseptic technique under USP 797. Work is done in primary engineering controls such as laminar airflow workbenches (ISO Class 5) inside cleanrooms.",
        "Technicians garb in order (shoe covers, hair cover, mask, hand hygiene, gown, sterile gloves), clean the hood, and work at least 6 inches inside. Hazardous drugs are prepared in biological safety cabinets. Beyond-use dates depend on risk category.",
    ], ["USP 797 = sterile compounding", "ISO Class 5 hood", "Work at least 6 inches inside the hood", "Hazardous drugs in a biological safety cabinet"]),
    (16, "Insurance and Billing", [
        "Third-party payers include private insurance, pharmacy benefit managers (PBMs), Medicare Part D, Medicaid, and workers' compensation. Claims are processed electronically using the patient's BIN, PCN, group, and member ID numbers.",
        "Common rejections include refill too soon, non-formulary drug, and prior authorization required. Terms include co-pay, coinsurance, deductible, and formulary tiers.",
    ], ["PBMs manage drug benefits", "Medicare Part D covers prescriptions", "Prior authorization may be required", "Formulary tiers affect co-pays"]),
    (17, "Inventory Control and Management", [
        "Inventory management keeps the right drugs in stock without excess. Methods include perpetual inventory, automated ordering, par levels, and turnover rates. Medications are purchased from wholesalers or directly from manufacturers.",
        "Technicians check expiration dates, rotate stock (first in, first out), handle returns and recalls, and store drugs correctly: room temperature (20–25°C), refrigerated (2–8°C), or frozen. Controlled substances need special ordering (DEA Form 222 for Schedule II) and counts.",
    ], ["Rotate stock: first in, first out", "Refrigerate at 2–8°C", "DEA Form 222 for Schedule II", "Handle recalls promptly"]),
    (18, "Medication Errors and Safety", [
        "Medication errors include wrong drug, dose, patient, route, or time. Causes include look-alike/sound-alike drug names, illegible handwriting, unsafe abbreviations, and distractions.",
        "Prevention includes tall man lettering (e.g., hydrOXYzine vs. hydrALAZINE), barcode scanning, using leading zeros, avoiding 'Do Not Use' abbreviations, and reporting errors to programs like MedWatch and ISMP.",
    ], ["Look-alike/sound-alike drugs cause errors", "Tall man lettering", "Barcode scanning", "Report errors to MedWatch/ISMP"]),
    (19, "Pharmacokinetics and Pharmacodynamics", [
        "Pharmacokinetics is what the body does to a drug: absorption, distribution, metabolism (mainly in the liver), and excretion (mainly by the kidneys), known as ADME. The first-pass effect reduces the amount of an oral drug reaching circulation. Half-life is the time for drug levels to fall by half.",
        "Pharmacodynamics is what the drug does to the body: drugs bind to receptors as agonists (activate) or antagonists (block). The therapeutic index compares toxic and effective doses; narrow-index drugs such as warfarin and digoxin need close monitoring.",
    ], ["ADME: absorption, distribution, metabolism, excretion", "Liver metabolizes; kidneys excrete", "Half-life = time for levels to halve", "Agonists activate; antagonists block"]),
    (20, "Microbiology and Infectious Disease", [
        "Microorganisms include bacteria, viruses, fungi, and protozoa. Bacteria are classified by shape and Gram stain. Infections can be local or systemic, and the body defends itself with immune responses.",
        "Antimicrobial resistance develops when drugs are overused or not taken as prescribed, so patients should finish their full course of antibiotics.",
    ], ["Bacteria, viruses, fungi, protozoa", "Gram-positive vs. Gram-negative", "Resistance from overuse", "Finish the full antibiotic course"]),
    (21, "Antibacterial Drugs", [
        "Antibacterial classes include penicillins (amoxicillin), cephalosporins (cephalexin), macrolides (azithromycin), tetracyclines (doxycycline, avoid dairy and antacids), fluoroquinolones (ciprofloxacin), aminoglycosides (gentamicin), sulfonamides (sulfamethoxazole/trimethoprim), and others such as vancomycin.",
        "Side effects include allergic reactions (especially with penicillins), GI upset, photosensitivity, and C. difficile infection.",
    ], ["Penicillin allergy is common", "Tetracyclines: avoid dairy", "Fluoroquinolones: -floxacin", "Antibiotics treat bacteria, not viruses"]),
    (22, "Antiviral Drugs", [
        "Antivirals treat viral infections by preventing viral replication. Examples include acyclovir and valacyclovir (herpes), oseltamivir (influenza, best within 48 hours), and antiretrovirals for HIV used in combination therapy.",
        "Vaccines prevent many viral diseases. Antivirals generally don't cure infections but control them.",
    ], ["Acyclovir for herpes", "Oseltamivir for flu (within 48 h)", "HIV: combination antiretrovirals", "Vaccines prevent viral disease"]),
    (23, "Antifungal Drugs", [
        "Antifungals treat infections such as athlete's foot, ringworm, yeast infections, and systemic fungal infections. Examples include fluconazole, clotrimazole, nystatin (oral thrush), terbinafine, and amphotericin B (serious systemic infections).",
        "Names often end in -azole. Topical forms treat skin infections; oral and IV forms treat deeper infections.",
    ], ["Names often end in -azole", "Nystatin for thrush", "Amphotericin B for serious infections", "Topical vs. systemic"]),
    (24, "Antiprotozoal Drugs", [
        "Antiprotozoal drugs treat infections caused by protozoa such as malaria (chloroquine and other antimalarials), giardiasis and trichomoniasis (metronidazole), and toxoplasmosis.",
        "Metronidazole should not be taken with alcohol because it causes severe nausea and vomiting.",
    ], ["Malaria: antimalarials like chloroquine", "Metronidazole for giardia and trichomonas", "No alcohol with metronidazole", "Protozoa are single-celled parasites"]),
    (25, "Therapeutic Drugs for the Nervous System", [
        "Nervous system drugs include analgesics (acetaminophen, NSAIDs, opioids), anesthetics, anticonvulsants (levetiracetam, phenytoin), drugs for Parkinson disease (levodopa/carbidopa), drugs for Alzheimer disease (donepezil), and migraine drugs (sumatriptan).",
        "Opioids can cause respiratory depression and constipation; naloxone reverses overdose. Many nervous system drugs are controlled substances.",
    ], ["Opioids: watch breathing; naloxone reverses", "Levodopa/carbidopa for Parkinson", "Donepezil for Alzheimer", "Anticonvulsants prevent seizures"]),
    (26, "Therapeutic Drugs for the Musculoskeletal System", [
        "Musculoskeletal drugs include NSAIDs (ibuprofen, naproxen) for pain and inflammation, muscle relaxants (cyclobenzaprine), drugs for gout (allopurinol, colchicine), drugs for osteoporosis (alendronate, taken upright with water), and disease-modifying drugs for rheumatoid arthritis (methotrexate).",
        "NSAIDs can cause stomach ulcers and kidney problems with long-term use.",
    ], ["NSAIDs reduce pain and inflammation", "Allopurinol for gout", "Alendronate: take upright with water", "Methotrexate for rheumatoid arthritis"]),
    (27, "Therapeutic Drugs for Mental Health Conditions", [
        "Antidepressants include SSRIs (fluoxetine, sertraline), SNRIs, tricyclics, and MAOIs (which interact dangerously with tyramine-rich foods). Anxiolytics include benzodiazepines (alprazolam, lorazepam, controlled substances) and buspirone.",
        "Antipsychotics (haloperidol, risperidone) treat schizophrenia; lithium stabilizes mood in bipolar disorder and needs blood level monitoring; stimulants (methylphenidate) treat ADHD.",
    ], ["SSRIs for depression", "MAOIs + tyramine = hypertensive crisis", "Benzodiazepines are controlled", "Lithium needs level monitoring"]),
    (28, "Therapeutic Drugs for the Endocrine System", [
        "Endocrine drugs include insulin (rapid-, short-, intermediate-, and long-acting) and oral diabetes drugs such as metformin, sulfonylureas, and newer GLP-1 agonists and SGLT2 inhibitors. Levothyroxine treats hypothyroidism; methimazole treats hyperthyroidism.",
        "Corticosteroids (prednisone) reduce inflammation, and hormones include estrogen, progesterone, and testosterone. Insulin is usually refrigerated before opening.",
    ], ["Insulin types by onset and duration", "Metformin first-line for type 2", "Levothyroxine for hypothyroidism", "Prednisone = corticosteroid"]),
    (29, "Therapeutic Drugs for the Cardiovascular System", [
        "Cardiovascular drugs include antihypertensives: ACE inhibitors (-pril, may cause dry cough), ARBs (-sartan), beta blockers (-olol), calcium channel blockers, and diuretics (furosemide, hydrochlorothiazide). Statins (-statin) lower cholesterol.",
        "Anticoagulants (warfarin, monitored with INR; heparin; newer drugs like apixaban) and antiplatelets (aspirin, clopidogrel) prevent clots. Nitroglycerin treats angina, and digoxin treats heart failure and arrhythmias.",
    ], ["-pril ACE inhibitors; -sartan ARBs; -olol beta blockers", "Statins lower cholesterol", "Warfarin monitored with INR", "Nitroglycerin for angina"]),
    (30, "Therapeutic Drugs for the Immune System", [
        "Immune system drugs include vaccines (active immunity), immune globulins (passive immunity), immunosuppressants for transplant patients (cyclosporine, tacrolimus), and biologic drugs (monoclonal antibodies ending in -mab) for autoimmune diseases and cancer.",
        "Antihistamines and epinephrine treat allergic reactions. Immunosuppressed patients are at higher risk of infection.",
    ], ["Vaccines = active immunity", "Immunosuppressants prevent transplant rejection", "-mab = monoclonal antibody", "Epinephrine for anaphylaxis"]),
    (31, "Therapeutic Drugs for the Respiratory System", [
        "Respiratory drugs include bronchodilators such as albuterol (short-acting rescue inhaler) and long-acting agents, inhaled corticosteroids (fluticasone) for long-term asthma control, leukotriene modifiers (montelukast), antihistamines (loratadine), decongestants (pseudoephedrine, sold behind the counter), and cough suppressants and expectorants (dextromethorphan, guaifenesin).",
        "Proper inhaler technique and rinsing the mouth after inhaled steroids (to prevent thrush) are important.",
    ], ["Albuterol = rescue inhaler", "Inhaled steroids for control; rinse mouth", "Pseudoephedrine behind the counter", "Guaifenesin = expectorant"]),
    (32, "Therapeutic Drugs for the Urinary System", [
        "Urinary drugs include diuretics, urinary antispasmodics for overactive bladder (oxybutynin), drugs for benign prostatic hyperplasia (tamsulosin, finasteride), urinary analgesics (phenazopyridine, which turns urine orange), and antibiotics for UTIs (nitrofurantoin).",
        "Drug doses often need adjustment in kidney disease because the kidneys excrete many drugs.",
    ], ["Oxybutynin for overactive bladder", "Tamsulosin and finasteride for BPH", "Phenazopyridine turns urine orange", "Adjust doses in kidney disease"]),
    (33, "Therapeutic Drugs for the Digestive System", [
        "Digestive drugs include antacids, H2 blockers (famotidine), proton pump inhibitors (omeprazole, -prazole) for GERD and ulcers, antiemetics (ondansetron), laxatives and stool softeners (docusate), antidiarrheals (loperamide), and drugs for inflammatory bowel disease.",
        "H. pylori ulcers are treated with antibiotics plus acid-reducing drugs.",
    ], ["PPIs end in -prazole", "H2 blockers: famotidine", "Ondansetron for nausea", "Loperamide for diarrhea"]),
    (34, "Therapeutic Drugs for the Reproductive System", [
        "Reproductive drugs include hormonal contraceptives (estrogen and progestin; effectiveness may be reduced by some antibiotics like rifampin), hormone replacement therapy, fertility drugs, drugs for erectile dysfunction (sildenafil, not used with nitrates), and testosterone.",
        "Many of these drugs are teratogenic or have special safety warnings.",
    ], ["Hormonal contraceptives", "Sildenafil: never with nitrates", "Rifampin reduces contraceptive effectiveness", "Testosterone is a controlled substance"]),
    (35, "Therapeutic Drugs for the Eyes, Ears, and Nose", [
        "Eye drugs include glaucoma drops (latanoprost, timolol), antibiotic and steroid eye drops and ointments, and artificial tears. Ophthalmic products must be sterile.",
        "Ear (otic) drugs treat infections and remove earwax; nasal products include steroid sprays and decongestant sprays (which can cause rebound congestion if overused).",
    ], ["Ophthalmic products must be sterile", "Latanoprost and timolol for glaucoma", "Otic = ear", "Decongestant sprays cause rebound congestion"]),
    (36, "Therapeutic Drugs for the Integumentary System", [
        "Skin drugs include topical corticosteroids (hydrocortisone) for inflammation, antibiotics (mupirocin), antifungals, acne treatments (benzoyl peroxide, retinoids such as isotretinoin, which requires the iPLEDGE program), and drugs for psoriasis.",
        "Sunscreens, wound care products, and treatments for lice and scabies (permethrin) are also covered.",
    ], ["Hydrocortisone = topical steroid", "Isotretinoin requires iPLEDGE", "Permethrin for lice and scabies", "Benzoyl peroxide for acne"]),
    (37, "Complementary and Alternative Medicine", [
        "Complementary and alternative medicine includes herbal supplements, vitamins, homeopathy, acupuncture, and other therapies. Dietary supplements are regulated less strictly than drugs (under DSHEA, 1994).",
        "Herbals can interact with medications: St. John's wort reduces the effectiveness of many drugs, and ginkgo and garlic increase bleeding risk with anticoagulants. Patients should tell the pharmacist about all supplements.",
    ], ["Supplements regulated under DSHEA", "St. John's wort interacts with many drugs", "Ginkgo increases bleeding risk", "Ask about all supplements"]),
]

